-- lil creature "claude": floats on every workspace, takes no focus, has no decoration.
-- Generated by `lil --print-hyprland-rules`. Regenerate if the instance name in lil.config.json changes.
hl.window_rule({
  match = { class = "^lil$", title = "^claude$" },
  float = true,
  pin = true,
  no_focus = true,
  border_size = 0,
  rounding = 0,
  no_blur = true,
  no_shadow = true,
  no_anim = true,
  no_dim = true,
})
